begin;
set local lock_timeout = '5s';
alter table public.configuracion_web add column if not exists horario text not null default '' constraint configuracion_web_horario_longitud check (length(horario)<=200);
update public.configuracion_web set horario='9:00 a. m. a 6:00 p. m.' where id=1 and horario='';
update public.vehiculos set ideal_para='El Changan Alsvin es una opción para organizar sus desplazamientos personales, visitas a clientes y trámites en Lima. Su formato sedán permite considerar una alternativa a una camioneta cuando la prioridad es la movilidad cotidiana. La unidad de la flota es de transmisión mecánica y bicombustible GLP; consulte si sus características se ajustan al recorrido que tiene previsto.

Consulte por WhatsApp la disponibilidad, tarifa, requisitos y garantía. Antes de confirmar, revise el kilometraje acordado, las coberturas, el combustible y las condiciones de entrega y devolución. Indique si necesita el vehículo por días, semanas o meses; el equipo evaluará su solicitud. Enviar una consulta no confirma una reserva.' where id='changan-alsvin' and coalesce(ideal_para,'')='';
update public.vehiculos set ideal_para='El Changan X7 Plus puede acompañar una agenda de reuniones, visitas familiares o desplazamientos de trabajo en Lima. Es una alternativa para quienes buscan una SUV de transmisión automática y desean comparar opciones para su movilidad personal o empresarial. Al cotizar, indique cuántas personas viajarán y el equipaje previsto para que nuestro equipo confirme la configuración de la unidad.

Consulte por WhatsApp la disponibilidad, tarifa, requisitos y garantía. Antes de confirmar, revise el kilometraje acordado, las coberturas, el combustible y las condiciones de entrega y devolución. Indique si necesita el vehículo por días, semanas o meses; el equipo evaluará su solicitud. Enviar una consulta no confirma una reserva.' where id='changan-x7-plus' and coalesce(ideal_para,'')='';
update public.vehiculos set ideal_para='La Ford Territory es una alternativa para quienes buscan una SUV automática para su agenda personal o ejecutiva en Lima. Puede considerarla para visitas comerciales, reuniones en distintas sedes o desplazamientos familiares. Esta unidad utiliza gasolina. Cuéntenos el uso previsto, el recorrido y las fechas: así podrá comparar su propuesta con otras camionetas de la flota antes de decidir.

Consulte por WhatsApp la disponibilidad, tarifa, requisitos y garantía. Antes de confirmar, revise el kilometraje acordado, las coberturas, el combustible y las condiciones de entrega y devolución. Indique si necesita el vehículo por días, semanas o meses; el equipo evaluará su solicitud. Enviar una consulta no confirma una reserva.' where id='ford-territory' and coalesce(ideal_para,'')='';
update public.vehiculos set ideal_para='El Hyundai Verna puede ser una opción para sus traslados cotidianos, reuniones de trabajo y gestiones en Lima. Su formato sedán permite evaluar una unidad para movilidad personal o de empresa sin elegir una SUV. La flota contempla versiones automáticas y mecánicas; indique su preferencia al cotizar. Confirme cuál está disponible para sus fechas y las características de la unidad ofrecida.

Consulte por WhatsApp la disponibilidad, tarifa, requisitos y garantía. Antes de confirmar, revise el kilometraje acordado, las coberturas, el combustible y las condiciones de entrega y devolución. Indique si necesita el vehículo por días, semanas o meses; el equipo evaluará su solicitud. Enviar una consulta no confirma una reserva.' where id='hyundai-verna' and coalesce(ideal_para,'')='';
update public.vehiculos set ideal_para='El Hyundai Accent es una alternativa de formato sedán para organizar una agenda de visitas, trámites o reuniones en Lima. Puede considerarlo para movilidad personal y para desplazamientos de colaboradores, según el uso acordado. Antes de elegir, solicite la versión, transmisión, año y características de la unidad disponible; la ficha del modelo no sustituye esa confirmación para su alquiler.

Consulte por WhatsApp la disponibilidad, tarifa, requisitos y garantía. Antes de confirmar, revise el kilometraje acordado, las coberturas, el combustible y las condiciones de entrega y devolución. Indique si necesita el vehículo por días, semanas o meses; el equipo evaluará su solicitud. Enviar una consulta no confirma una reserva.' where id='hyundai-accent' and coalesce(ideal_para,'')='';
update public.vehiculos set ideal_para='El JAC JS8 es una alternativa SUV para comparar cuando necesita organizar traslados familiares o de trabajo. La unidad de la flota cuenta con transmisión automática y sistema bicombustible GLP. Indique el número de ocupantes, el equipaje y el recorrido previsto para confirmar que la configuración ofrecida se ajusta a su necesidad. La atención y coordinación se realizan desde Surco.

Consulte por WhatsApp la disponibilidad, tarifa, requisitos y garantía. Antes de confirmar, revise el kilometraje acordado, las coberturas, el combustible y las condiciones de entrega y devolución. Indique si necesita el vehículo por días, semanas o meses; el equipo evaluará su solicitud. Enviar una consulta no confirma una reserva.' where id='jac-s8' and coalesce(ideal_para,'')='';
update public.vehiculos set ideal_para='El Jetour X70 puede considerarse para movilidad familiar o empresarial cuando busca una alternativa SUV. Para elegir con información suficiente, indique cuántas personas viajarán, qué equipaje llevarán y las fechas previstas. Consulte la versión, transmisión y capacidad de la unidad disponible antes de contratar. Nuestro equipo puede orientarle al comparar esta opción con las demás camionetas del catálogo.

Consulte por WhatsApp la disponibilidad, tarifa, requisitos y garantía. Antes de confirmar, revise el kilometraje acordado, las coberturas, el combustible y las condiciones de entrega y devolución. Indique si necesita el vehículo por días, semanas o meses; el equipo evaluará su solicitud. Enviar una consulta no confirma una reserva.' where id='jetur-x70' and coalesce(ideal_para,'')='';
update public.vehiculos set ideal_para='La Suzuki Ertiga es una alternativa de la categoría familiar para quienes necesitan planificar traslados con varios acompañantes. Su transmisión automática puede ser una preferencia al elegir su próxima unidad. Indique la cantidad de pasajeros y el equipaje antes de confirmar: ocupar todas las plazas cambia el espacio disponible para maletas. Consulte la configuración ofrecida y las condiciones del recorrido.

Consulte por WhatsApp la disponibilidad, tarifa, requisitos y garantía. Antes de confirmar, revise el kilometraje acordado, las coberturas, el combustible y las condiciones de entrega y devolución. Indique si necesita el vehículo por días, semanas o meses; el equipo evaluará su solicitud. Enviar una consulta no confirma una reserva.' where id='suzuki-ertiga' and coalesce(ideal_para,'')='';
update public.vehiculos set ideal_para='El Changan CX70 permite evaluar una opción SUV de transmisión mecánica para movilidad personal o de trabajo. La unidad utiliza sistema bicombustible GLP. Puede compararla con otros modelos del catálogo según su recorrido, número de acompañantes y fechas de alquiler. Si habrá más de un conductor, indíquelo al cotizar para revisar la documentación y las condiciones aplicables antes de contratar.

Consulte por WhatsApp la disponibilidad, tarifa, requisitos y garantía. Antes de confirmar, revise el kilometraje acordado, las coberturas, el combustible y las condiciones de entrega y devolución. Indique si necesita el vehículo por días, semanas o meses; el equipo evaluará su solicitud. Enviar una consulta no confirma una reserva.' where id='changan-cx70' and coalesce(ideal_para,'')='';
update public.vehiculos set ideal_para='El Glory 560 es una alternativa SUV de transmisión mecánica para organizar su movilidad en Lima. Puede considerarlo al comparar unidades para una agenda de trabajo o desplazamientos personales. La unidad de la flota utiliza sistema bicombustible GLP. Comparta el lugar de uso, la duración estimada y las necesidades de sus acompañantes para recibir una propuesta ajustada a su solicitud.

Consulte por WhatsApp la disponibilidad, tarifa, requisitos y garantía. Antes de confirmar, revise el kilometraje acordado, las coberturas, el combustible y las condiciones de entrega y devolución. Indique si necesita el vehículo por días, semanas o meses; el equipo evaluará su solicitud. Enviar una consulta no confirma una reserva.' where id='glory-560' and coalesce(ideal_para,'')='';
update public.vehiculos set ideal_para='El Glory 580 puede ser una alternativa para quienes desean comparar una SUV mecánica para sus traslados familiares o de empresa. Su sistema bicombustible GLP forma parte de la información de esta unidad. Confirme la capacidad y disposición de asientos, especialmente si llevará varios pasajeros con equipaje. Explique su itinerario para revisar el uso autorizado y la disponibilidad para sus fechas.

Consulte por WhatsApp la disponibilidad, tarifa, requisitos y garantía. Antes de confirmar, revise el kilometraje acordado, las coberturas, el combustible y las condiciones de entrega y devolución. Indique si necesita el vehículo por días, semanas o meses; el equipo evaluará su solicitud. Enviar una consulta no confirma una reserva.' where id='glory-580' and coalesce(ideal_para,'')='';
update public.vehiculos set ideal_para='El Toyota Yaris es una alternativa sedán de transmisión mecánica para quienes buscan organizar desplazamientos personales o una agenda de gestiones en Lima. La unidad de la flota es del año 2010 y utiliza sistema bicombustible GLP. Considere esos datos al comparar modelos y solicite información actual de la unidad antes de decidir. La propuesta se prepara según sus fechas y recorrido.

Consulte por WhatsApp la disponibilidad, tarifa, requisitos y garantía. Antes de confirmar, revise el kilometraje acordado, las coberturas, el combustible y las condiciones de entrega y devolución. Indique si necesita el vehículo por días, semanas o meses; el equipo evaluará su solicitud. Enviar una consulta no confirma una reserva.' where id='toyota-yaris' and coalesce(ideal_para,'')='';
commit;
